'use client';

import { FormEvent, useEffect, useMemo, useState } from 'react';

type Priority = 'high' | 'medium' | 'low';

type Todo = {
  id: number;
  title: string;
  completed: boolean;
  due_date: string | null;
  priority: Priority;
  created_at: string;
};

const PRIORITY_ORDER: Record<Priority, number> = {
  high: 0,
  medium: 1,
  low: 2,
};

const PRIORITY_LABEL: Record<Priority, string> = {
  high: 'High',
  medium: 'Medium',
  low: 'Low',
};

const PRIORITY_COLOR: Record<Priority, { background: string; text: string; border: string }> = {
  high: { background: '#fee2e2', text: '#991b1b', border: '#fecaca' },
  medium: { background: '#fef3c7', text: '#92400e', border: '#fde68a' },
  low: { background: '#dbeafe', text: '#1e40af', border: '#bfdbfe' },
};

export default function HomePage() {
  const [title, setTitle] = useState('');
  const [priority, setPriority] = useState<Priority>('medium');
  const [priorityFilter, setPriorityFilter] = useState<Priority | 'all'>('all');
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;

    const loadTodos = async () => {
      try {
        const response = await fetch('/api/todos');
        if (!response.ok) {
          throw new Error('Failed to load todos');
        }

        const payload = (await response.json()) as { todos?: Todo[] };
        if (isMounted) {
          setTodos(payload.todos ?? []);
          setError(null);
        }
      } catch {
        if (isMounted) {
          setError('Could not load todos.');
        }
      } finally {
        if (isMounted) {
          setLoading(false);
        }
      }
    };

    void loadTodos();

    return () => {
      isMounted = false;
    };
  }, []);

  const visibleTodos = useMemo(() => {
    if (priorityFilter === 'all') {
      return todos;
    }

    return todos.filter((todo) => todo.priority === priorityFilter);
  }, [todos, priorityFilter]);

  const pendingTodos = useMemo(() => {
    const onlyPending = visibleTodos.filter((todo) => !todo.completed);

    return [...onlyPending].sort((a, b) => {
      const byPriority = PRIORITY_ORDER[a.priority] - PRIORITY_ORDER[b.priority];
      if (byPriority !== 0) {
        return byPriority;
      }

      return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
    });
  }, [visibleTodos]);

  const completedTodos = useMemo(
    () => visibleTodos.filter((todo) => todo.completed),
    [visibleTodos]
  );

  const addTodo = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const cleaned = title.trim();
    if (!cleaned) {
      return;
    }

    const selectedPriority = priority;
    setTitle('');
    setPriority('medium');
    setError(null);

    const response = await fetch('/api/todos', {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
      },
      body: JSON.stringify({ title: cleaned, priority: selectedPriority }),
    });

    if (!response.ok) {
      setError('Unable to create todo.');
      return;
    }

    const payload = (await response.json()) as { todo: Todo };
    setTodos((current) => [payload.todo, ...current]);
    setError(null);
  };

  const setTodoCompleted = async (todo: Todo, completed: boolean) => {
    setTodos((current) =>
      current.map((item) => (item.id === todo.id ? { ...item, completed } : item))
    );

    const response = await fetch(`/api/todos/${todo.id}`, {
      method: 'PUT',
      headers: {
        'content-type': 'application/json',
      },
      body: JSON.stringify({ completed }),
    });

    if (!response.ok) {
      setError('Unable to update todo.');
      setTodos((current) =>
        current.map((item) => (item.id === todo.id ? { ...item, completed: todo.completed } : item))
      );
      return;
    }

    setError(null);
  };

  const deleteTodo = async (todo: Todo) => {
    setError(null);

    const response = await fetch(`/api/todos/${todo.id}`, {
      method: 'DELETE',
    });

    if (!response.ok) {
      setError('Unable to delete todo.');
      return;
    }

    setTodos((current) => current.filter((item) => item.id !== todo.id));
    setError(null);
  };

  return (
    <main style={{ maxWidth: 900, margin: '0 auto', padding: '40px 20px' }}>
      <h1 style={{ marginTop: 0, marginBottom: 20, fontSize: 38 }}>Todo Dashboard</h1>

      <form onSubmit={addTodo} style={{ display: 'grid', gap: 10, marginBottom: 22 }}>
        <label htmlFor="todo-title" style={{ fontWeight: 700 }}>
          Title
        </label>
        <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
          <input
            id="todo-title"
            value={title}
            onChange={(event) => setTitle(event.target.value)}
            placeholder="What needs to be done?"
            style={{
              flex: 1,
              height: 44,
              borderRadius: 10,
              border: '1px solid #cbd5e1',
              padding: '0 12px',
              fontSize: 16,
            }}
          />
          <div style={{ display: 'grid', gap: 6 }}>
            <label htmlFor="todo-priority" style={{ fontWeight: 700 }}>
              Priority
            </label>
            <select
              id="todo-priority"
              value={priority}
              onChange={(event) => setPriority(event.target.value as Priority)}
              style={{
                height: 44,
                borderRadius: 10,
                border: '1px solid #cbd5e1',
                padding: '0 10px',
                fontSize: 15,
                background: '#ffffff',
              }}
            >
              <option value="high">High</option>
              <option value="medium">Medium</option>
              <option value="low">Low</option>
            </select>
          </div>
          <button
            type="submit"
            style={{
              border: 'none',
              borderRadius: 10,
              padding: '0 18px',
              background: '#0f766e',
              color: '#ffffff',
              fontWeight: 700,
            }}
          >
            Add Todo
          </button>
        </div>
      </form>

      {error ? (
        <p role="alert" style={{ color: '#991b1b', fontWeight: 700 }}>
          {error}
        </p>
      ) : null}

      {loading ? <p>Loading...</p> : null}

      {!loading && todos.length === 0 ? <p>No todos yet</p> : null}

      <div style={{ display: 'grid', gap: 6, maxWidth: 260 }}>
        <label htmlFor="priority-filter" style={{ fontWeight: 700 }}>
          Filter by priority
        </label>
        <select
          id="priority-filter"
          value={priorityFilter}
          onChange={(event) => setPriorityFilter(event.target.value as Priority | 'all')}
          style={{
            height: 40,
            borderRadius: 10,
            border: '1px solid #cbd5e1',
            padding: '0 10px',
            fontSize: 15,
            background: '#ffffff',
          }}
        >
          <option value="all">All Priorities</option>
          <option value="high">High Priority</option>
          <option value="medium">Medium Priority</option>
          <option value="low">Low Priority</option>
        </select>
      </div>

      <section style={{ marginTop: 24 }}>
        <h2 style={{ marginBottom: 10 }}>Pending ({pendingTodos.length})</h2>
        <ul
          data-testid="pending-list"
          style={{ listStyle: 'none', padding: 0, margin: 0, display: 'grid', gap: 10 }}
        >
          {pendingTodos.map((todo) => (
            <li
              key={todo.id}
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                border: '1px solid #dbeafe',
                backgroundColor: '#ffffff',
                borderRadius: 10,
                padding: 12,
              }}
            >
              <label style={{ display: 'flex', alignItems: 'center', gap: 10, flex: 1 }}>
                <input
                  type="checkbox"
                  checked={todo.completed}
                  aria-label={`Mark ${todo.title} complete`}
                  onChange={(event) => {
                    void setTodoCompleted(todo, event.target.checked);
                  }}
                />
                <span>{todo.title}</span>
              </label>
              <span
                data-testid={`priority-badge-${todo.priority}`}
                style={{
                  fontWeight: 700,
                  fontSize: 12,
                  borderRadius: 999,
                  border: `1px solid ${PRIORITY_COLOR[todo.priority].border}`,
                  background: PRIORITY_COLOR[todo.priority].background,
                  color: PRIORITY_COLOR[todo.priority].text,
                  padding: '4px 8px',
                  marginRight: 8,
                }}
              >
                {PRIORITY_LABEL[todo.priority]}
              </span>
              <button
                type="button"
                aria-label={`Delete ${todo.title}`}
                onClick={() => {
                  void deleteTodo(todo);
                }}
                style={{
                  borderRadius: 8,
                  border: '1px solid #fecaca',
                  background: '#fee2e2',
                  color: '#991b1b',
                  fontWeight: 700,
                  padding: '7px 10px',
                }}
              >
                Delete
              </button>
            </li>
          ))}
        </ul>
      </section>

      <section style={{ marginTop: 30 }}>
        <h2 style={{ marginBottom: 10 }}>Completed ({completedTodos.length})</h2>
        <ul style={{ listStyle: 'none', padding: 0, margin: 0, display: 'grid', gap: 10 }}>
          {completedTodos.map((todo) => (
            <li
              key={todo.id}
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                border: '1px solid #d1fae5',
                backgroundColor: '#ffffff',
                borderRadius: 10,
                padding: 12,
              }}
            >
              <label style={{ display: 'flex', alignItems: 'center', gap: 10, flex: 1 }}>
                <input
                  type="checkbox"
                  checked={todo.completed}
                  aria-label={`Mark ${todo.title} complete`}
                  onChange={(event) => {
                    void setTodoCompleted(todo, event.target.checked);
                  }}
                />
                <span style={{ textDecoration: 'line-through', color: '#64748b' }}>{todo.title}</span>
              </label>
              <span
                data-testid={`priority-badge-${todo.priority}`}
                style={{
                  fontWeight: 700,
                  fontSize: 12,
                  borderRadius: 999,
                  border: `1px solid ${PRIORITY_COLOR[todo.priority].border}`,
                  background: PRIORITY_COLOR[todo.priority].background,
                  color: PRIORITY_COLOR[todo.priority].text,
                  padding: '4px 8px',
                  marginRight: 8,
                }}
              >
                {PRIORITY_LABEL[todo.priority]}
              </span>
              <button
                type="button"
                aria-label={`Delete ${todo.title}`}
                onClick={() => {
                  void deleteTodo(todo);
                }}
                style={{
                  borderRadius: 8,
                  border: '1px solid #fecaca',
                  background: '#fee2e2',
                  color: '#991b1b',
                  fontWeight: 700,
                  padding: '7px 10px',
                }}
              >
                Delete
              </button>
            </li>
          ))}
        </ul>
      </section>
    </main>
  );
}